{
  "findings": [
    {
      "check_id": "CKV_AWS_355",
      "title": "IAM policy allows wildcard resource for SageMaker actions",
      "resource": "aws_iam_policy.privesc-sageMakerCreatePresignedNotebookURL-policy",
      "severity": "MEDIUM",
      "explanation": "The IAM policy grants 'sagemaker:CreatePresignedNotebookInstanceUrl' and 'sagemaker:ListNotebookInstances' on Resource = "*". This violates the principle of least privilege by allowing these actions on all SageMaker notebook instances in the account, rather than restricting them to specific resources."
    }
  ],
  "patched_code": "resource "aws_iam_policy" "privesc-sageMakerCreatePresignedNotebookURL-policy" {
  name        = "privesc-sageMakerCreatePresignedNotebookURL-policy"
  path        = "/"
  description = "Allows privesc via sagemakerCreatePresignedNotebookURL"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action = [
          "sagemaker:CreatePresignedNotebookInstanceUrl",
          "sagemaker:ListNotebookInstances"
        ]
        # TODO: Replace with specific ARNs or use a variable to restrict scope
        Resource = "arn:aws:sagemaker:*:*:notebook-instance/*"
      },
    ]
  })
}",
  "fix_summary": "Replaced the wildcard Resource "*" with a more restrictive ARN pattern scoped specifically to SageMaker notebook instances (arn:aws:sagemaker:*:*:notebook-instance/*). While still broad due to lack of specific instance names in the source code, this limits the permission surface to only the relevant resource type, addressing the CKV_AWS_355 finding regarding unrestricted resources for restrictable actions."
}
